/* Tooltips: the explanation of every option, keyed by the option's label text. The words in -dashes are the MAME options behind them. */
#include "common.h"

static const struct { const wchar_t *key, *text; } tips[] = {
    /* General */
    {L"MAME Program",
     L"mame.exe, the emulator that runs the games. Leave it empty to use mame.exe next to this launcher (or in a folder named mame next to it).\nAny current MAME will do; the games are handled by its own drivers (zn.cpp, namcos10/11/12.cpp, hng64.cpp, konamigv.cpp, ksys573.cpp, taitogn.cpp)."},
    {L"ROMs Folder",
     L"Folder (or several, separated by ;) that holds the game ROM sets: zip or 7z files, or folders. Put the BIOS sets (coh1000c.zip for ZN-1, coh3002c.zip for ZN-2, konamigv.zip, sys573.zip, coh3002t.zip / coh1002t.zip for Taito G-Net, hng64.zip ...; the Check ROM Set window names the one a game needs) and the parent sets of clones there as well.\nA relative path starts in the launcher's folder. Empty: the roms folder of MAME (-rompath of its own settings)."},
    {L"Browse…", L"Choose the folder or the program."},
    {L"Clear MAME Program", L"Empties the MAME program box: the launcher looks for mame.exe next to itself again."},
    {L"Clear ROMs Folder", L"Empties the ROMs folder box (after a question): the roms folder of MAME is used."},
    {L"Browse BIOS Folder", L"Choose the folder with the BIOS zip files."},
    {L"Clear BIOS Folder", L"Empties the BIOS folder box: the BIOS sets are looked for in the ROMs folder again."},
    {L"BIOS Folder", L"Where the BIOS sets (for example neogeo.zip, hng64.zip, skns.zip, the System 11 / 12 or ZN BIOS) are. MAME gets it as one more path of -rompath. Empty: the BIOS sets are in the ROMs folder, as before."},
    {L"List Only Available ROMs",
     L"Only show games whose ROM set (and parent / BIOS set) is in the ROMs folder."},
    {L"Hide Console",
     L"Starts MAME without its black console window.\nApplies to games started from the launcher and from frontends, not to desktop icons."},
    {L"Enable Logs",
     L"Writes the log files of the launcher in the logs folder beside it: mame-ex-launch.log (the command line of the last start), mame-ex-output.log (what MAME printed), mame-ex-combos.log and mame-ex-input.log (what the Lua plugins see). Off by default: then no log file is written."},
    {L"Theme",
     L"The look of the launcher: System follows the Windows app colour mode, Light or Dark.\nThe theme changes after a restart: when you press OK you are asked whether to restart now. The same choice is in the View menu."},
    {L"When A Game Starts",
     L"What the launcher does when you start a game.\nKeep The Launcher Open: nothing (the default).\nMinimize The Launcher: it is minimized while the game runs and comes back when the game ends.\nClose The Launcher: it closes, the game goes on without it. Desktop icons are not affected."},
    {L"Classic Layout",
     L"Ticked: the General, Video, Audio, Controls and Combos tabs are on the right of the game list (the classic layout).\nUnticked: the tabs are in a window of their own, so the game list has the whole main window. Open it with the Settings button, Options > Settings… or F9.\nThe layout changes when you press OK. The same choice is in the View menu."},
    {L"Restore Defaults",
     L"Restores the Video, Audio and General options (including the Advanced group at the bottom of the General tab) to their defaults (MAME's own defaults).\nThe MAME program, the ROMs folder, the favorites, the window layout and the Controls and Combos tabs are kept."},
    {L"Reset Filters",
     L"Sets the Hardware, Region, Maker and Genre filters back to All and puts the game list back in its normal order (by number, ascending). The filters and the order are remembered for the next start."},
    {L"Hardware Filter",
     L"Shows only the games of one arcade board: Sony ZN-1 / ZN-2, Taito FX-1A / FX-1B / G-Net, Tecmo TPS, Namco System 10 / 11 / 12, Konami GV / System 573, SNK Hyper Neo Geo 64 ... The Hardware column of the list shows the same."},
    {L"Region Filter",
     L"Shows only the games of one region: US, JP, ASIA, EUROPE or WORLD. The region is read from the words between ( ) in the game's name; a game that does not say is listed as Other."},
    {L"Maker Filter",
     L"Shows only the games of one maker (from the manufacturer text of MAME, e.g. Namco, Capcom, Tecmo)."},
    {L"Genre Filter",
     L"Shows only fighting games, shooters, racing games ... The genre is guessed from the game's name, so some games are listed as Other."},
    /* Video */
    {L"Video Mode",
     L"-video: how MAME draws.\nAuto lets MAME choose. BGFX is the modern renderer (HLSL / CRT effects, Direct3D 11/12, OpenGL or Vulkan); Direct3D and OpenGL are the older ones; GDI is software and slow."},
    {L"Fullscreen",
     L"-window / -nowindow: run the game fullscreen instead of in a window. Also switchable with Alt+Enter in the game."},
    {L"Resolution",
     L"-resolution: the size of the window, or of the fullscreen picture, taken from the modes your display supports.\nAuto (MAME's choice) fits the window to the game.."},
    {L"Rotation",
     L"-norotate, -ror, -rol, -flipx -flipy: rotates the picture.\nGame Default uses the game's own orientation (a vertical game such as Tenkomori Shooting is then rotated for a normal monitor)."},
    {L"Keep Aspect Ratio",
     L"-keepaspect: keeps the shape of the picture (4:3 for these boards, with black bars) instead of stretching it to the window."},
    {L"Uneven Stretch",
     L"-unevenstretch: lets the picture be scaled by a non-whole number in one direction only when that gives a bigger picture (sharper than stretching in both). On by default in MAME."},
    {L"Integer Scale (Pixel Perfect)",
     L"-intscalex / -intscaley: draws the picture an exact whole number of times (1x - 8x) of the game's own pixels: sharp pixels, square pixels, black bars around it. Off lets MAME scale freely. If the window is smaller than the picture it will not fit: pick a smaller factor.\nThis is MAME's version of the original launcher's Pixel Perfect aspect ratio. Internal resolution was a feature of the ZiNc Direct3D 11 renderer and does not exist in MAME; xBRZ, FXAA and dither smoothing are in the Filter Window group."},
    {L"Bilinear Filter",
     L"-filter: smooths the enlarged picture instead of showing blocky pixels."},
    {L"Prescale",
     L"-prescale: enlarges the picture by a whole number before the smooth scaling (1 - 8): sharper pixels with the bilinear filter. Needs a faster graphics card at higher values."},
    {L"Wait For V-Sync",
     L"-waitvsync: shows each frame in step with the screen refresh, which removes tearing. Can add a little input delay."},
    {L"Sync Refresh Rate",
     L"-syncrefresh: only run a game at its own refresh rate if the screen can show that rate (the game then runs at its exact speed; it needs -waitvsync to be useful)."},
    {L"Throttle (Real Speed)",
     L"-throttle: keeps the game at its normal speed. Turn it off to run as fast as the PC allows (the game will be too fast). F10 toggles it in the game."},
    {L"Frame Skip",
     L"-frameskip / -autoframeskip: skips drawing some frames when the PC is too slow, so the game keeps its speed. Off by default; Auto lets MAME decide."},
    {L"Maximize Window",
     L"-maximize: starts the window maximized (only when not fullscreen)."},
    {L"HLSL (Direct3D Only)",
     L"-hlsl_enable: MAME's classic HLSL post-processing (scanlines, shadow mask, curvature ...) of the Direct3D video mode. Only works with Video Mode Direct3D; it is greyed out for the others.\nWith BGFX use BGFX Screen Effect instead. The HLSL settings themselves (scanline strength ...) are in MAME: Tab > Slider Controls, or the hlsl options of mame.ini."},
    {L"GLSL (OpenGL Only)",
     L"-gl_glsl: lets the OpenGL video mode use GLSL shaders (a filter and your own shader files). Only works with Video Mode OpenGL; it is greyed out for the others. With BGFX use BGFX Screen Effect, with Direct3D use HLSL."},
    {L"GLSL Filter",
     L"-gl_glsl_filter: how the GLSL path scales the picture: Plain (sharp), Bilinear (smooth, MAME's default) or Bicubic (smoother, slower)."},
    {L"GLSL Shader Name",
     L"-glsl_shader_screen0: the name of a GLSL shader set from MAME's glsl folder (the files glsl\\<name>.vsh and .fsh without the extension), applied to the game screen. Leave it empty for no shader."},
    {L"Filter Window",
     L"Experimental. MAME runs in a plain window of the game's own picture size; a second window copies that picture every frame, runs the pixel shaders of the original ZiNc EX renderer over it (xBRZ, FXAA, dither smoothing) and shows the result over the whole screen: in 4:3 with black bars when Keep Aspect Ratio is ticked, else stretched to the screen. The window is click-through and never takes the focus, so keys and mouse go to MAME. It shows only while MAME has the focus (Alt+Tab shows the desktop).\nNeeds Windows 8.1 or newer and works with the Direct3D and OpenGL video modes best. The picture is copied from the MAME window, so it adds about a frame of delay; Internal Resolution cannot be raised (MAME draws these games at their own resolution). Do not use MAME's own fullscreen (Alt+Enter) with it. Desktop icons start MAME without the filter."},
    {L"Filter Scaler",
     L"How the picture is enlarged.\nSmooth (Bilinear): soft, a little blurry.\nSharp (Pixels): hard square pixels.\nxBRZ: the pixel-art scaler, clean smooth edges on diagonals and curves of 2D art (3D textures stay blocky).\nSharp Bilinear: sharp pixels with only a thin blend along their edges: crisp, without the shimmer of hard pixels.\nSmooth 3D (Bicubic): a Mitchell bicubic filter: smoother than bilinear and without boxy texels, best for the 3D games (Tekken, Soul Calibur ...)."},
    {L"FXAA Filter",
     L"A fast filter over the finished picture that smooths jagged edges (also of 2D art), at a slight softening."},
    {L"Dither Smoothing",
     L"Reduces the checkerboard dither pattern that some games bake into their backgrounds: a pixel that differs a little from four alike neighbours is blended with them. Low only touches very faint patterns; High also smooths stronger ones (and may soften very fine detail)."},
    {L"BGFX Screen Effect",
     L"-bgfx_screen_chains: the picture effect of the BGFX video mode: HLSL imitates a CRT monitor (scanlines, curvature), CRT Geometry / Deluxe are shader CRT looks, LCD Grid a pixel grid. Default leaves it to MAME. Only works with Video Mode BGFX (or Auto when that picks BGFX)."},
    {L"BGFX Backend",
     L"-bgfx_backend: which graphics API BGFX uses: Direct3D 11, Direct3D 12, OpenGL or Vulkan. Default leaves it to MAME."},
    {L"Crop Artwork",
     L"-artwork_crop: crops artwork so the game picture fills the window in one direction. (Which artwork is shown is chosen in MAME: Tab > Video Options.)"},
    /* Audio */
    {L"Sound",
     L"-sound: the sound output of MAME. Auto lets MAME choose; Off mutes the game and makes it a little faster."},
    {L"Sample Rate",
     L"-samplerate: the sound output rate. Default is MAME's own (48000 Hz)."},
    {L"Volume Attenuation (dB)",
     L"-volume: makes the game quieter by this many decibels (0 - 32). 0 is full volume."},
    {L"Audio Latency",
     L"-audio_latency: how much sound MAME buffers (1 - 5). Higher is safer against crackling but delays the sound."},
    /* Controls */
    {L"Enable Joysticks",
     L"-joystick: lets MAME use game controllers. Turn it off if a connected pad or stick disturbs the keyboard controls."},
    {L"Controller Provider",
     L"-joystickprovider: how MAME talks to the controllers: Auto, Windows (hybrid XInput + DirectInput), DirectInput or XInput."},
    {L"Enable Mouse",
     L"-mouse: lets MAME read the mouse (the mouse pointer is then captured by the game)."},
    {L"Enable Light Gun",
     L"-lightgun: lets MAME read light gun / mouse aiming. Needed for the shooting games of System 11 / 12: Point Blank 2, Gunbarl, Ghoul Panic, Oh! Bakyuuun. (Beast Busters: Second Nightmare of Hyper Neo Geo 64 uses it too.)"},
    {L"Allow Contradictory Directions",
     L"-joystick_contradictory: allows pressing left and right (or up and down) at the same time, as arcade sticks with a restrictor never do. Off by default."},
    {L"Joystick Dead Zone %",
     L"-joystick_deadzone: how far the stick must move (in %) before it counts. MAME's default is 30."},
    {L"Joystick Saturation %",
     L"-joystick_saturation: how far the stick has to move (in %) to count as fully pushed. MAME's default is 85."},
    {L"Controller File",
     L"-ctrlr: a controller configuration of MAME's ctrlr folder (a .cfg file with a ready-made button mapping). None leaves the mapping alone.\nThe buttons of a game are set in MAME itself: press Tab in the game, then Input (this Machine). MAME keeps the mapping in its cfg folder."},
    {L"Set Key…", L"Press the key you want for the chosen action (Esc cancels, Delete leaves the action without a key). Also: double-click the Keyboard cell."},
    {L"Set Pad…", L"Press a button (or move the D-pad or stick, for a direction) of the pad or stick you want for the chosen action. XInput pads (Xbox) and other pads and arcade sticks are found. Pad Number: Automatic uses the pad that was pressed; if MAME numbers your pads differently, pick the number. Also: double-click the Pad cell."},
    {L"Clear Binding", L"Takes the key and the pad button off the chosen action: it then does nothing until you set one."},
    {L"Mapping Overrides MAME's Game Settings", L"MAME saves keys and buttons you changed inside a game (Tab menu) in cfg\\<game>.cfg, and those win over cfg\\default.cfg, where this tab writes. With this on, the actions of the list below are removed from the game's file before each start (a copy stays as <game>.cfg.mame-ex-backup), so this mapping always applies."},
    {L"HLSL Settings…", L"The parameters of MAME's HLSL screen effects (the shaders bloom.fx, chroma.fx, scanline.fx ... in MAME's hlsl folder): scanlines, shadow mask, screen curvature, bloom, colour, phosphor, NTSC. Choose a preset or change single values; only values that differ from MAME's defaults are passed. Needs the Direct3D video mode and HLSL ticked."},
    {L"Rewind", L"-rewind: keeps rewind save states, so you can step back in time while the game runs (uses memory: see All MAME Options for the size). Only works for games whose driver supports save states."},
    {L"All MAME Options…", L"Every command line option of MAME that the other tabs have no control for (about 160: BIOS, gamma / brightness, screenshots, recording, input recording, rewind, speed, per-OS video and input options ...), with MAME's own description. Only values that differ from MAME's defaults are passed. An option that your MAME version does not know makes MAME stop with an error: change only what you need."},
    {L"Brightness", L"-brightness: screen brightness correction (0.1 - 2.0, MAME's default 1.0)."},
    {L"Contrast", L"-contrast: screen contrast correction (0.1 - 2.0, default 1.0)."},
    {L"Gamma", L"-gamma: screen gamma correction (0.1 - 3.0, default 1.0)."},
    {L"Aspect Ratio", L"-aspect: aspect ratio of all screens, e.g. 4:3 or 16:9 (auto: MAME's choice)."},
    {L"BGFX Shadow Mask", L"-bgfx_shadow_mask: name of the shadow mask texture the BGFX screen effects use (default slot-mask.png, in MAME's artwork / bgfx folders)."},
    {L"BGFX LUT", L"-bgfx_lut: name of the colour LUT texture the BGFX screen effects use (default lut-default.png)."},
    {L"Device", L"-lightgun_device: what drives the light gun controls of games that have them (Point Blank ...): the keyboard (MAME's default), the mouse, a real light gun, a joystick, or nothing. Needs Enable Light Gun for a real gun."},
    {L"Provider", L"-lightgunprovider: the Windows module that reads light guns and mice used as guns (Auto: MAME's choice)."},
    {L"Speed", L"-speed: speed of the game relative to real time (1.0 = normal; 0.5 = half speed; 0.1 - 100)."},
    {L"Snapshot Size", L"-snapsize: size of screenshots and movies as <width>x<height> (auto: the smallest that fits)."},
    {L"Record Video To", L"-aviwrite: writes an AVI movie of every session to this file name (empty: no recording). The file is replaced at every start."},
    {L"Record Audio To", L"-wavwrite: writes the sound of every session to this WAV file (empty: no recording)."},
    {L"Record Input To", L"-record: records your inputs to this file in MAME's inp folder (empty: no recording). Play it back with Play Input From."},
    {L"Play Input From", L"-playback: plays back an input recording made with Record Input To (empty: no playback)."},
    {L"Load State", L"-state: a saved state to load when the game starts: a slot (0 - 9, a, b ...) or a file name (empty: none)."},
    {L"Autofire Speed", L"How often an autofire button (the Autofire column of the mapping list) is pressed while you hold it: 10, 15, 20 or 30 presses per second."},
    {L"Profile", L"Mappings you saved under a name. Choosing one loads it into the list below; press OK to write it to MAME."},
    {L"Save Profile", L"Saves the mapping of the list into the chosen profile."},
    {L"Save As…", L"Saves the mapping of the list as a new profile (or replaces one with the same name)."},
    {L"Rename Profile", L"Gives the chosen profile another name."},
    {L"Delete Profile", L"Deletes the chosen profile. The list keeps its mapping."},
    {L"Reset Mapping", L"Gives every action of the list back to MAME's defaults (keys and automatic pad mapping): the entries of these actions are removed from MAME's cfg\\default.cfg when you press OK."},
    /* Advanced */
    {L"Skip Game Info Screen",
     L"-skip_gameinfo: skips the screen with the game information at the start. The warning screen (the yellow \"There are known problems with this system\") is skipped by the next option."},
    {L"Skip Game Warning Screen",
     L"MAME has no option for its warning screen, it waits for a key. With this on the launcher sends an unused key (F13) to the MAME window while the game starts, so the screen goes away on its own, and MAME is started with -keyboardprovider dinput (DirectInput takes such a key, and keeps Alt+Enter working)."},
    {L"Auto Save / Restore State",
     L"-autosave: saves the state of the game when you quit and restores it at the next start (where MAME supports save states for the game)."},
    {L"Cheats",
     L"-cheat: enables the cheat engine of MAME (needs cheat files in its cheat folder)."},
    {L"Confirm Quit",
     L"-confirm_quit: asks before closing the game when you press Esc."},
    {L"Extra Arguments",
     L"More MAME command line words that are added to every start, for example -bios or -debug. See the MAME documentation (mame -showusage). The settings of the launcher come first; these come last and win."},
};

const wchar_t *tip_for(const wchar_t *label) {
    size_t i;
    for (i = 0; i < sizeof tips / sizeof tips[0]; i++)
        if (_wcsicmp(tips[i].key, label) == 0) return tips[i].text;   /* labels are matched without regard to case */
    return NULL;
}
